def square(n):
    return n * n

print(square(5))  # 25

try:
    int("abc")
except ValueError:
    print("not a number")

d = {"a": 1}
e = d.copy()
d.clear()
print(e, d)  # {'a': 1} {}

try:
    x = 10 / 2
except ZeroDivisionError:
    print("nope")
else:
    print("ok:", x)  # ok: 5.0
finally:
    print("done")  # done

try:
    int("abc")
except ValueError as e:
    print("bad:", e)  # bad: invalid literal for int() with base 10: 'abc'

def check(n):
    if n < 0:
        raise ValueError("must be >= 0")
    return n
print(check(5))  # 5

class TooSmallError(Exception):
    pass
try:
    raise TooSmallError("tiny!")
except TooSmallError as e:
    print("caught:", e)  # caught: tiny!

def to_int(s):
    try:
        return int(s)
    except ValueError:
        return -1
print(to_int("42"), to_int("x"))  # 42 -1

for v in ["7", "x", []]:
    try:
        print(int(v))  # 7, then errors
    except (ValueError, TypeError):
        print("bad input")  # bad input

try:
    n = int("42")
except ValueError:
    n = 0
else:
    print("parsed:", n)  # parsed: 42

def demo():
    try:
        return "early"
    finally:
        print("cleanup runs")  # cleanup runs
print(demo())  # early

for i in range(4):
    if i == 1:
        continue
    if i == 3:
        break
    print(i)  # 0 / 2

def keys_of(**info):
    return sorted(info)
keys_of(name="Ada", city="Pune")  # ['city', 'name']

def loud(fn):
    return lambda *a: fn(*a).upper()
@loud
def hi(): return "hello"
hi()  # 'HELLO'

def stats(nums):
    return min(nums), max(nums)
lo, hi = stats([3, 1, 9])
print(lo, hi)  # 1 9

def greet(*, name):
    return "Hi " + name
print(greet(name="Ada"))
